package com.gamehub;
import com.gamehub.application.*; import com.gamehub.infrastructure.*; import org.junit.jupiter.api.Test; import java.nio.file.*; import java.time.*; import static org.junit.jupiter.api.Assertions.*;
class SessionSliceTest { @Test void sessionRequiresConfirmedReservationAndRejectsDuplicateActive() throws Exception {Path p=Files.createTempFile("session-", ".db");try(Database db=new Database(p)){var us=new UserService(db);us.bootstrap("m","password1");var manager=us.authenticate("m","password1");var u=us.registerCustomer("Session Customer","sess@example.com","03001234004","password2");var o=new OperationsService(db);long station=o.addStation(manager.id(),"S-01","PC","",50000);long reservation=o.reserve(u.id(),station,Instant.now().plusSeconds(3600),Instant.now().plusSeconds(7200));long session=o.startSession(manager.id(),reservation);assertTrue(session>0);assertThrows(IllegalStateException.class,()->o.startSession(manager.id(),reservation));assertEquals(session,o.finishSession(manager.id(),session,5000));}finally{Files.deleteIfExists(p);}}}
